import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"61、【中孚】 兑下巽上","description":"温公易说 - 61、【中孚】 兑下巽上","frontmatter":{"title":"61、【中孚】 兑下巽上","description":"温公易说 - 61、【中孚】 兑下巽上"},"headers":[],"relativePath":"zh/classics/wengong/062.md","filePath":"zh/classics/wengong/062.md"}'),n={name:"zh/classics/wengong/062.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_61、【中孚】-兑下巽上" tabindex="-1">61、【中孚】 兑下巽上 <a class="header-anchor" href="#_61、【中孚】-兑下巽上" aria-label="Permalink to “61、【中孚】 兑下巽上”">​</a></h1><h3 id="彖曰-中孚-柔在内而刚得中-说而巽-孚乃化邦也。豚鱼吉-信及豚鱼也。利涉大川-乘木舟虚也。中孚以利贞-乃应乎天也。" tabindex="-1">彖曰：中孚，柔在内而刚得中，说而巽，孚乃化邦也。豚鱼吉，信及豚鱼也。利涉大川，乘木舟虚也。中孚以利贞，乃应乎天也。 <a class="header-anchor" href="#彖曰-中孚-柔在内而刚得中-说而巽-孚乃化邦也。豚鱼吉-信及豚鱼也。利涉大川-乘木舟虚也。中孚以利贞-乃应乎天也。" aria-label="Permalink to “彖曰：中孚，柔在内而刚得中，说而巽，孚乃化邦也。豚鱼吉，信及豚鱼也。利涉大川，乘木舟虚也。中孚以利贞，乃应乎天也。”">​</a></h3><p>中孚者，发于中而孚于人也。豚鱼，幽贱无知之物，茍饲以时，则应声而集，而况于人乎？至诚以涉险，如乘虚舟，物莫之害，故曰利涉大川，乘木舟虚也。</p><h3 id="象曰-泽上有风-中孚。君子以议狱缓死。" tabindex="-1">象曰：泽上有风，中孚。君子以议狱缓死。 <a class="header-anchor" href="#象曰-泽上有风-中孚。君子以议狱缓死。" aria-label="Permalink to “象曰：泽上有风，中孚。君子以议狱缓死。”">​</a></h3><h3 id="初九-虞吉-有他不燕-象曰-初九虞吉-志未变也。" tabindex="-1">初九：虞吉，有他不燕 象曰：初九虞吉，志未变也。 <a class="header-anchor" href="#初九-虞吉-有他不燕-象曰-初九虞吉-志未变也。" aria-label="Permalink to “初九：虞吉，有他不燕 象曰：初九虞吉，志未变也。”">​</a></h3><h3 id="九二-鸣鹤在阴-其子和之。我有好爵-吾与尔靡之-象曰-其子和之-中心愿也。" tabindex="-1">九二：鸣鹤在阴，其子和之。我有好爵，吾与尔靡之 象曰：其子和之，中心愿也。 <a class="header-anchor" href="#九二-鸣鹤在阴-其子和之。我有好爵-吾与尔靡之-象曰-其子和之-中心愿也。" aria-label="Permalink to “九二：鸣鹤在阴，其子和之。我有好爵，吾与尔靡之 象曰：其子和之，中心愿也。”">​</a></h3><p>鸣鹤在阴，其子和之，言至诚以待物，无远不应。</p><h3 id="六三-得敌-或鼓或罢-或泣或歌-象曰-或鼓或罢-位不当也。" tabindex="-1">六三：得敌，或鼓或罢，或泣或歌 象曰：或鼓或罢，位不当也。 <a class="header-anchor" href="#六三-得敌-或鼓或罢-或泣或歌-象曰-或鼓或罢-位不当也。" aria-label="Permalink to “六三：得敌，或鼓或罢，或泣或歌 象曰：或鼓或罢，位不当也。”">​</a></h3><h3 id="六四-月几望-马匹亡-无咎-象曰-马匹亡-绝类上也。" tabindex="-1">六四：月几望，马匹亡，无咎 象曰：马匹亡，绝类上也。 <a class="header-anchor" href="#六四-月几望-马匹亡-无咎-象曰-马匹亡-绝类上也。" aria-label="Permalink to “六四：月几望，马匹亡，无咎 象曰：马匹亡，绝类上也。”">​</a></h3><h3 id="九五-有孚-挛如-无咎-象曰-有孚挛如-位正当也。" tabindex="-1">九五：有孚，挛如，无咎 象曰：有孚挛如，位正当也。 <a class="header-anchor" href="#九五-有孚-挛如-无咎-象曰-有孚挛如-位正当也。" aria-label="Permalink to “九五：有孚，挛如，无咎 象曰：有孚挛如，位正当也。”">​</a></h3><h3 id="上九-翰音登于天-贞凶-象曰-翰音登于天-何可长也。" tabindex="-1">上九：翰音登于天，贞凶 象曰：翰音登于天，何可长也。 <a class="header-anchor" href="#上九-翰音登于天-贞凶-象曰-翰音登于天-何可长也。" aria-label="Permalink to “上九：翰音登于天，贞凶 象曰：翰音登于天，何可长也。”">​</a></h3>',11)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
